function creerSubject() {
  let value;
  let error;
  let completed;
  const subscribers = new Set();

  const next = (val) => {
    value = val;
    subscribers.forEach(s => s.next(val));
  };

  const error = (err) => {
    error = err;
    subscribers.forEach(s => s.error(err));
  };

  const complete = () => {
    completed = true;
    subscribers.forEach(s => s.complete());
  };

  const subscribe = ({ next, error, complete }) => {
    subscribers.add({ next, error, complete });
    return {
      next: (val) => next(val),
      error: (err) => error(err),
      complete: () => complete()
    };
  };

  return { next, error, complete, subscribe };
}
