  let attempts = 0;
  let lastError = null;
  let isOpen = false;
  let resetTimer = null;

  const executeWithCircuitBreaker = async (...args) => {
    if (isOpen) {
      throw new Error('Circuit open'); // Simulate circuit breaker trip
    }

    try {
      const result = await fn(...args);
      attempts = 0;
      lastError = null;
      return result;
    } catch (err) {
      attempts++;
      lastError = err;

      if (attempts >= seuil && !isOpen) {
        isOpen = true;
        console.log(`Circuit opened after ${seuil} consecutive failures`);
        setTimeout(() => {
          isOpen = false;
          attempts = 0;
          lastError = null;
          clearTimeout(resetTimer); // Clear any existing timer before setting a new one
          resetTimer = setTimeout(() => console.log('Circuit half-open'), delaiResetMs);
        }, delaiResetMs);
      }

      throw err;
    }
  };

  return executeWithCircuitBreaker;
}
