function creerCircuitBreaker(fn, seuil, delaiResetMs) {
    let state = 'ferme'; // closed, open, half-open
    let lastFailureTime = null;
    let consecutiveFailures = 0;

    return async function(...args) {
        if (state === 'ferme') {
            try {
                const result = await fn(...args);
                if (state === 'half-open') {
                    state = 'ferme';
                }
                return result;
            } catch (err) {
                consecutiveFailures++;
                lastFailureTime = Date.now();
                if (consecutiveFailures >= seuil) {
                    state = 'ouvert';
                }
                throw err;
            }
        } else if (state === 'ouvert') {
            const now = Date.now();
            if (lastFailureTime && now - lastFailureTime < delaiResetMs) {
                throw new Error('Circuit breaker is open');
            }
            // Attempt to reset state after delay
            setTimeout(() => {
                state = 'half-open';
                consecutiveFailures = 0;
            }, delaiResetMs);
        } else if (state === 'half-open') {
            try {
                const result = await fn(...args);
                if (state === 'ferme') {
                    state = 'ferme'; // Reset to closed after successful call
                }
                return result;
            } catch (err) {
                consecutiveFailures++;
                lastFailureTime = Date.now();
                if (consecutiveFailures >= seuil) {
                    state = 'ouvert';
                } else {
                    throw err;
                }
            }
        }
    };
}
