function remplirMatrice(grille, x, y, nouvelleValeur) {
    // Check bounds
    if (x < 0 || y < 0 || x >= grille[0].length || y >= grille.length) {
        return false; // Invalid coordinates
    }

    // Fill the cell and flood fill neighbors
    const queue = [[x, y]];
    const visited = new Set();
    visited.add(`${x},${y}`);

    while (queue.length > 0) {
        const [currentX, currentY] = queue.shift();
        grille[currentY][currentX] = nouvelleValeur;

        // Check neighbors in all four directions
        const neighbors = [
            [currentX + 1, currentY],
            [currentX - 1, currentY],
            [currentX, currentY + 1],
            [currentX, currentY - 1]
        ];

        for (const [nx, ny] of neighbors) {
            if (nx >= 0 && ny >= 0 && nx < grille[0].length && ny < grille.length && !visited.has(`${nx},${ny}`)) {
                queue.push([nx, ny]);
                visited.add(`${nx},${ny}`);
            }
        }
    }

