function medianeDeuxTries(a, b) {
    let m = a.length, n = b.length;
    if (m > n) return medianeDeuxTries(b, a); // Ensure a is the smaller array
    let low = 0, high = m;
    while (low <= high) {
        const partitionX = Math.floor((low + high) / 2);
        const partitionY = Math.floor((a.length + b.length + 1) / 2 - partitionX);
        const maxLeftX = (partitionX === 0) ? -Infinity : a[partitionX - 1];
        const minRightX = (partitionX === m) ? Infinity : a[partitionX];
        const maxLeftY = (partitionY === 0) ? -Infinity : b[partitionY - 1];
        const minRightY = (partitionY === n) ? Infinity : b[partitionY];
        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            return Math.max(maxLeftX, maxLeftY);
        } else if (maxLeftX > minRightY) {
            high = partitionX - 1;
        } else {
            low = partitionX + 1;
        }
    }
    return Infinity; // Shouldn't reach here for sorted arrays
}
