function fusionnerIntervalles(tab) {
    if (tab.length === 0) return [];

    // Sort intervals by start time
    tab.sort((a, b) => a[0] - b[0]);

    const merged = [tab[0]];

    for (let i = 1; i < tab.length; i++) {
        const last = merged[merged.length - 1];
        if (tab[i][0] <= last[1]) {
            // Overlapping intervals, merge them
            last[1] = Math.max(last[1], tab[i][1]);
        } else {
            merged.push(tab[i]);
        }
    }

    return merged;
}
```
**Explication**: Cette fonction fusionne les intervalles superposés en triant d'abord les intervalles par leur début, puis en parcourant et en fusionnant ceux qui se chevauchent.

